import React, { useState } from 'react';
import Table from './components/Table';
import './App.css';

function App() {
  const [tables, setTables] = useState([]);
  const [selectedTable, setSelectedTable] = useState(null);

  const addTable = () => {
    const newTableId = tables.length + 1;
    setTables([...tables, newTableId]);
  };

  return (
    <div className="App">
      <div className="sidebar">
        <button className="add-table-btn" onClick={addTable}>Add Table</button>
        <div className="table-list">
          {tables.map(tableId => (
            <div
              key={tableId}
              className={`table-item ${selectedTable === tableId ? 'active' : ''}`}
              onClick={() => setSelectedTable(tableId)}
            >
              Table {tableId}
            </div>
          ))}
        </div>
      </div>
      <div className="main-content">
        {selectedTable ? (
          <Table tableId={selectedTable} />
        ) : (
          <div className="no-table-selected">Select a table or add a new one</div>
        )}
      </div>
    </div>
  );
}

export default App;
